function init(){$('analysis').onchange=setup;$('category').onchange=render;$('market').onchange=marketChanged;$('county').onchange=render;$('radius').onchange=render;setup();}
function mode(){return $('analysis').value}function marketChanged(){if(mode()==='Neighborhood Targeting')setupCounty();else render()}
function setup(){const m=mode(),s=$('market');$('stageNotice').classList.add('hidden');$('view').style.display='block';$('marketWrap').style.display='block';$('countyWrap').style.display='none';$('radiusWrap').style.display='none';
 if(m==='Media Market'){s.innerHTML=DMA.slice().sort((a,b)=>a.dma.localeCompare(b.dma)).map(x=>`<option value="${x.dma_code}">${x.dma}</option>`).join('');if(DMA.some(x=>x.dma_code===751))s.value='751';}
 else{s.innerHTML=METRO.map(x=>`<option value="${x.cbsa}">${x.metro}</option>`).join('');if(METRO.some(x=>x.cbsa==='19740'))s.value='19740';if(m==='Neighborhood Targeting'){ $('countyWrap').style.display='block';$('radiusWrap').style.display='block';setupCounty();return;}}
 render();}
function setupCounty(){const cb=$('market').value,cs=COUNTY.filter(x=>x.cbsa===cb).sort((a,b)=>a.county.localeCompare(b.county));$('county').innerHTML=cs.map(x=>`<option value="${x.fips}">${x.county} County</option>`).join('');if(cb==='19740'&&cs.some(x=>x.fips==='08031'))$('county').value='08031';render();}
function cards(items){$('kpis').innerHTML=items.map(x=>`<div><b>${x[1]}</b><span>${x[0]}</span></div>`).join('')}function bars(rows,label,val){$('bars').innerHTML=rows.slice(0,12).map((r,i)=>`<div class="barrow"><span>${i+1}. ${label(r)}</span><div class="track"><div class="fill" style="width:${Math.max(0,Math.min(100,val(r)))}%"></div></div><b>${score(val(r))}</b></div>`).join('')}function metrics(items){$('why').innerHTML=items.map(m=>`<div class="metric"><span>${m[0]}</span><b>${m[1]}</b></div>`).join('')}
function render(){const cat=$('category').value,m=mode();if(m==='Media Market')return renderDMA(cat);if(m==='Market Expansion')return renderMetro(cat);if(m==='Local Opportunity')return renderCounty(cat);return renderZIP(cat)}

function indexDirection(value){
  const v=Number(value);
  if(!Number.isFinite(v)) return 'not available';
  if(v>=110) return 'well above the U.S. average';
  if(v>=102) return 'above the U.S. average';
  if(v>98) return 'about in line with the U.S. average';
  if(v>90) return 'below the U.S. average';
  return 'well below the U.S. average';
}
function interpretationPanel(cat,replacement,need,marketSize){
  const category=categoryName(cat);
  $('metrics').innerHTML=`
    <div class="metric"><div><b>Replacement Potential</b><div class="sub">Measures how strongly the area's housing stock and ownership characteristics suggest homes are entering the ${category.toLowerCase()} replacement cycle. This market is <b>${indexDirection(replacement)}</b>.</div></div></div>
    <div class="metric"><div><b>${category} Need</b><div class="sub">Measures the physical housing characteristics associated with greater need for ${category.toLowerCase()} replacement or service. This market is <b>${indexDirection(need)}</b>.</div></div></div>
    <div class="metric"><div><b>Homeowner Market Size</b><div class="sub">Measures the relative scale of the addressable homeowner audience. This market is <b>${indexDirection(marketSize)}</b> on the analyzer's market-size index.</div></div></div>
    <div class="sub" style="margin-top:14px"><b>Index guide:</b> 100 = U.S. average. Above 100 indicates greater-than-average potential or need; below 100 indicates less-than-average potential or need.</div>`;
}

function renderDMA(cat){const code=+$('market').value,key=cat+'_opportunity',sorted=rankRows(DMA,key),x=DMA.find(r=>r.dma_code===code)||sorted[0];updateConditions(cat,'Media Market',x,sorted);cards([['Market Opportunity',score(x[key])],[upgradeLabel(cat),index100(x.replacement_ready,DMA,'replacement_ready')],[serviceNeedLabel(cat),index100(x[cat+'_need'],DMA,cat+'_need')],['Homeowner Market Size',score(x.market_scale)]]);$('chartTitle').textContent='U.S. Media Market Opportunity';$('chartNote').textContent='Market opportunity across 83 DMAs using replacement potential, category need and homeowner market size.';$('marketName').textContent=x.dma;$('whyTitle').textContent='What the Numbers Tell Us';interpretationPanel(cat,index100(x.replacement_ready,DMA,'replacement_ready'),index100(x[cat+'_need'],DMA,cat+'_need'),score(x.market_scale));$('method').textContent='Market Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size';bars(sorted,r=>r.dma,r=>r[key]);$('tableTitle').textContent='Media Market Rankings';$('thead').innerHTML='<tr><th>Rank</th><th>DMA</th><th>Market Opportunity</th><th>Homeowner Households</th><th>ZIP Codes</th></tr>';$('rankings').innerHTML=sorted.map((r,i)=>`<tr data-code="${r.dma_code}"><td>${i+1}</td><td>${r.dma}</td><td><b>${score(r[key])}</b></td><td>${fmt(r.owner_hh)}</td><td>${r.zip_count}</td></tr>`).join('');rowClicks()}
function renderMetro(cat){const code=$('market').value,key=cat,sorted=rankRows(METRO,key),x=METRO.find(r=>r.cbsa===code)||sorted[0];updateConditions(cat,'Market Expansion',x,sorted);cards([['Market Expansion Score',score(x[key])],['Business Establishments',fmt(x[cat+'_estab'])],['Businesses with 10+ Employees',fmt(x[cat+'_10plus'])],['Businesses with 50+ Employees',fmt(x[cat+'_50plus'])],['Contractor Market Strength',score(x.contractor_ecosystem)]]);$('chartTitle').textContent='U.S. Metro Expansion Opportunity';$('chartNote').textContent='387 metropolitan statistical areas only — micropolitan areas are excluded. Business counts reflect the selected category.';$('marketName').textContent=x.metro;$('whyTitle').textContent='What the Numbers Tell Us';$('metrics').innerHTML=`<div class="metric"><div><b>Market Expansion</b><div class="sub">Measures the strength of this metro as a business-development market for the selected home-services category, using the category-specific employer and contractor model.</div></div></div><div class="metric"><div><b>Business Establishments</b><div class="sub">Counts employer establishments in the selected home-services category within this metro. The 10+ and 50+ measures identify progressively larger potential business prospects.</div></div></div><div class="metric"><div><b>Contractor Market Strength</b><div class="sub">Measures the depth and economic strength of the metro's contractor ecosystem. It is a market-context signal, not a count of prospective advertisers.</div></div></div>`;$('method').textContent='Market Expansion uses the CBSA employer/contractor model. Business counts shown are specific to the selected category.';bars(sorted,r=>r.metro,r=>r[key]);$('tableTitle').textContent='Metro Rankings — The Operator';$('thead').innerHTML='<tr><th>Rank</th><th>Metro</th><th>Market Expansion</th><th>Business Establishments</th><th>10+ Employees</th><th>50+ Employees</th></tr>';$('rankings').innerHTML=sorted.map((r,i)=>`<tr data-code="${r.cbsa}"><td>${i+1}</td><td>${r.metro}</td><td><b>${score(r[key])}</b></td><td>${fmt(r[cat+'_estab'])}</td><td>${fmt(r[cat+'_10plus'])}</td><td>${fmt(r[cat+'_50plus'])}</td></tr>`).join('');rowClicks()}
function renderCounty(cat){const code=$('market').value,sorted=COUNTY.filter(r=>r.cbsa===code).sort((a,b)=>b[cat+'_score']-a[cat+'_score']),x=sorted[0],metro=METRO.find(r=>r.cbsa===code);if(!x)return;updateConditions(cat,'Local Opportunity',x,sorted);cards([['Top County Score',score(x[cat+'_score'])],['Replacement Potential Households',fmt(x.replacement_ready_hh)],['Homeowner Households',fmt(x.owner_hh)],[serviceNeedLabel(cat),score(x[cat+'_need'])],['Homeowner Market Size',score(x.addressable_scale)]]);$('chartTitle').textContent=(metro?metro.metro:'Selected Metro')+' — County Opportunity';$('chartNote').textContent='Counties are ranked only within the selected Metro. Scores use the residential housing and homeowner data available for each ZIP Code.';$('marketName').textContent=x.county+' County';$('whyTitle').textContent='What the Numbers Tell Us';interpretationPanel(cat,index100(x.replacement_ready,COUNTY,'replacement_ready'),index100(x[cat+'_need'],COUNTY,cat+'_need'),score(x.market_scale));$('method').textContent='Local Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size. DMA Scarborough is not represented as county-level measurement.';bars(sorted,r=>r.county,r=>r[cat+'_score']);$('tableTitle').textContent='County Rankings — The Branch';$('thead').innerHTML='<tr><th>Rank</th><th>County</th><th>Local Opportunity</th><th>Replacement Potential Households</th><th>Homeowner Households</th><th>ZIP Codes</th></tr>';$('rankings').innerHTML=sorted.map((r,i)=>`<tr><td>${i+1}</td><td>${r.county}</td><td><b>${score(r[cat+'_score'])}</b></td><td>${fmt(r.replacement_ready_hh)}</td><td>${fmt(r.owner_hh)}</td><td>${r.zip_count}</td></tr>`).join('')}
function miles(a,b,c,d){const R=3958.8,p=Math.PI/180,x=(c-a)*p,y=(d-b)*p,q=Math.sin(x/2)**2+Math.cos(a*p)*Math.cos(c*p)*Math.sin(y/2)**2;return 2*R*Math.asin(Math.sqrt(q))}
function renderZIP(cat){const cb=$('market').value,fips=$('county').value,rad=+$('radius').value;let base=ZIP.filter(r=>r.cbsa===cb&&r.fips===fips),rows=base;if(rad>0&&base.length){const center=base.slice().sort((a,b)=>b.households-a.households)[0];rows=ZIP.filter(r=>r.cbsa===cb&&miles(center.lat,center.lon,r.lat,r.lon)<=rad)}const sorted=rows.slice().sort((a,b)=>b[cat+'_score']-a[cat+'_score']),x=sorted[0],metro=METRO.find(r=>r.cbsa===cb);if(!x)return;updateConditions(cat,'Neighborhood Targeting',x,sorted);cards([['Top ZIP Score',score(x[cat+'_score'])],['Replacement Potential Households',fmt(x.replacement_ready_hh)],['Homeowner Households',fmt(x.owner_hh)],[serviceNeedLabel(cat),score(x[cat+'_need'])],['ZIP Codes in View',sorted.length]]);$('chartTitle').textContent=(metro?metro.metro:'Selected Metro')+' — Neighborhood Targeting';$('chartNote').textContent=rad?`Residential ZIP Codes within ${rad} miles of the selected county's household center ZIP.`:'Residential ZIP Codes in the selected county.';$('marketName').textContent='ZIP '+x.zip+' · '+x.county+' County';$('whyTitle').textContent='What the Numbers Tell Us';metrics([[upgradeLabel(cat),index100(x.replacement_ready,ZIP,'replacement_ready')],[serviceNeedLabel(cat),index100(x[cat+'_need'],ZIP,cat+'_need')],['Homeowner Market Size',score(x.addressable_scale)],['Homeowner Rate',score(x.owner_rate)+'%'],['Single-Family Home Rate',score(x.sf_rate)+'%']]);$('method').textContent='ZIP Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size. No Scarborough propensity is represented as ZIP-level measurement.';bars(sorted,r=>'ZIP '+r.zip,r=>r[cat+'_score']);$('tableTitle').textContent='ZIP Rankings — The Local Pro';$('thead').innerHTML='<tr><th>Rank</th><th>ZIP</th><th>County</th><th>Neighborhood Opportunity</th><th>Replacement Potential Households</th><th>Homeowner Households</th><th>Homeowner %</th><th>Single-Family %</th></tr>';$('rankings').innerHTML=sorted.map((r,i)=>`<tr><td>${i+1}</td><td>${r.zip}</td><td>${r.county}</td><td><b>${score(r[cat+'_score'])}</b></td><td>${fmt(r.replacement_ready_hh)}</td><td>${fmt(r.owner_hh)}</td><td>${score(r.owner_rate)}%</td><td>${score(r.sf_rate)}%</td></tr>`).join('')}
function rowClicks(){document.querySelectorAll('#rankings tr[data-code]').forEach(tr=>tr.onclick=()=>{$('market').value=tr.dataset.code;if(mode()==='Neighborhood Targeting')setupCounty();else render();window.scrollTo({top:0,behavior:'smooth'})})}window.addEventListener('load',init);

// Market Conditions layer: descriptive statistics are intentionally separate from scoring.
const INDUSTRY={
 hvac:{title:'HVAC industry pulse',text:"AHRI's July 2026 U.S. heating and cooling equipment shipment release provides the latest national manufacturer-shipment context. It is national context, not a local demand estimate.",source:'AHRI · July 2026 U.S. Heating and Cooling Equipment Shipments'},
 roofing:{title:'Home improvement & repair pulse',text:'Harvard JCHS projects owner-occupied home improvement and repair spending of about $519B through mid-2027, with year-over-year growth slowing to 0.5% by 2027 Q2.',source:'Harvard Joint Center for Housing Studies · LIRA · July 23, 2026'},
 windows:{title:'Home improvement & repair pulse',text:'Harvard JCHS projects owner-occupied home improvement and repair spending of about $519B through mid-2027, with year-over-year growth slowing to 0.5% by 2027 Q2.',source:'Harvard Joint Center for Housing Studies · LIRA · July 23, 2026'}
};
function pct(n){return Number(n||0).toFixed(1)+'%'}
function money(n){return n?('$'+Math.round(n).toLocaleString()):'—'}
function weighted(rows,key,weight='households'){const den=rows.reduce((s,r)=>s+(+r[weight]||0),0);return den?rows.reduce((s,r)=>s+(+r[key]||0)*(+r[weight]||0),0)/den:0}
function conditionCards(items,cat){$('conditions').innerHTML=items.map(x=>`<div class="condition-card"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');const i=INDUSTRY[cat];$('industry').innerHTML=`<strong>${i.title}</strong>${i.text}<div class="source-note">Source: ${i.source}. Local housing statistics come from the analyzer's validated housing/ZIP source layer. These statistics do not alter the Market Opportunity.</div>`}
function updateConditions(cat,m,x,rows){let items=[];
 if(m==='Media Market'){items=[['Households',fmt(x.households)],['Owner households',fmt(x.owner_hh)],['Homeownership',pct(100*x.owner_hh/Math.max(1,x.households))],['Residential ZIP Codes',fmt(x.zip_count)]];}
 else if(m==='Market Expansion'){const z=ZIP.filter(r=>r.cbsa===x.cbsa);items=[['Households',fmt(z.reduce((s,r)=>s+r.households,0))],['Owner households',fmt(z.reduce((s,r)=>s+r.owner_hh,0))],['Homeownership',pct(weighted(z,'owner_rate'))],['Single-family homes',pct(weighted(z,'sf_rate'))],['Older housing stock',pct(weighted(z,'old_rate'))],['Median HH income',money(weighted(z,'income'))]];}
 else if(m==='Local Opportunity'){const z=ZIP.filter(r=>r.fips===x.fips);items=[['Households',fmt(x.households)],['Owner households',fmt(x.owner_hh)],['Homeownership',pct(weighted(z,'owner_rate'))],['Single-family homes',pct(weighted(z,'sf_rate'))],['Older housing stock',pct(weighted(z,'old_rate'))],['Long-tenure households',pct(weighted(z,'tenure_rate'))]];}
 else {items=[['Households',fmt(x.households)],['Owner households',fmt(x.owner_hh)],['Homeownership',pct(x.owner_rate)],['Single-family homes',pct(x.sf_rate)],['Older housing stock',pct(x.old_rate)],['Long-tenure households',pct(x.tenure_rate)],['Median HH income',money(x.income)],['Median home value',money(x.home_value)]];}
 conditionCards(items,cat);
}

const METHOD={
 'Media Market':{label:'DMA — The Ad Shop',purpose:'Media-market homeowner opportunity. This layer answers where replacement potential, category need and homeowner market size are strongest at the DMA level.',formula:'Market Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size.',data:'DMA values use the analyzer housing/household source layer. Consumer Demand is not used because comparable measured demand is not available for every market.',caution:'DMA scores are relative 0–100 opportunity measures. No DMA measure is represented as Metro, County or ZIP measurement.'},
 'Market Expansion':{label:'Metro — The Operator',purpose:'Business/market expansion opportunity. This layer answers which metropolitan areas have the strongest contractor/employer ecosystem for category expansion.',formula:'Market Expansion Score uses the validated CBSA employer/contractor model, including employer establishments, larger establishments and contractor ecosystem measures.',data:'CBSA is the authoritative market identifier. The view is restricted to metropolitan statistical areas; micropolitan areas are excluded.',caution:'Scarborough DMA data is not forced into Metro geography. Market Conditions are descriptive and do not alter the Market Expansion Score.'},
 'Local Opportunity':{label:'County — The Branch',purpose:'Local branch opportunity inside the selected Metro. This layer identifies where replacement-potential households and structural service need are concentrated.',formula:'Local Market Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size.',data:'County values are rebuilt from the validated residential ZIP housing layer for counties belonging to the selected Metro.',caution:'DMA Scarborough propensity may provide market context, but it is not represented as county-level measurement. Scores rank counties within the selected Metro.'},
 'Neighborhood Targeting':{label:'ZIP — The Local Pro',purpose:'Neighborhood targeting and service-area prioritization. This layer identifies residential ZIPs with the strongest local opportunity.',formula:'ZIP Market Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size.',data:'Residential ZIP inputs include homeownership, single-family concentration, housing age, residence tenure, household economics and addressable household scale. Radius views include qualifying residential ZIPs around the selected county center ZIP.',caution:'No Scarborough propensity is represented as ZIP-level measurement. ZIP scores are relative opportunity measures, not forecasts of leads, sales, revenue or market share.'}
};
function methodologyHTML(){const x=METHOD[mode()];return `<p><b>${x.label}</b></p><div class="method-section"><h3>What this view answers</h3><p>${x.purpose}</p></div><div class="method-section"><h3>How the score is calculated</h3><div class="method-formula">${x.formula}</div></div><div class="method-section"><h3>Data used</h3><p>${x.data}</p></div><div class="method-section"><h3>How to read this page</h3><p><b>Market Opportunity</b> determines the ranking. <b>Market Conditions</b> are reported/observed statistics that help explain the selected geography. <b>Industry Pulse</b> provides broader category context. Market Conditions and Industry Pulse do not change the score unless explicitly identified as score inputs.</p></div><div class="method-section"><h3>Interpretation</h3><div class="method-caution">${x.caution} Market Opportunity scores remain 0–100 relative prioritization measures. Measures shown against the U.S. average use 100 as the national benchmark and are not forecasts of leads, sales, revenue or market share.</div></div>`}
function openMethod(){ $('methodModalTitle').textContent='Methodology · '+METHOD[mode()].label; $('methodBody').innerHTML=methodologyHTML(); $('methodModal').classList.remove('hidden') }
function csvEscape(v){v=String(v??'');return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function exportCSV(){const table=document.querySelector('table'),rows=[...table.querySelectorAll('tr')].map(tr=>[...tr.children].map(td=>csvEscape(td.innerText.trim())).join(','));const blob=new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='home-services-'+mode().toLowerCase().replace(/\s+/g,'-')+'-'+$('category').value+'-rankings.csv';a.click();URL.revokeObjectURL(a.href)}
window.addEventListener('DOMContentLoaded',()=>{$('methodBtn').onclick=openMethod;$('methodClose').onclick=()=> $('methodModal').classList.add('hidden');$('methodModal').onclick=e=>{if(e.target===$('methodModal'))$('methodModal').classList.add('hidden')};$('csvBtn').onclick=exportCSV});

// Production controls and geographic QA enhancements.
function rankRows(rows,key){const dir=$('rankDir')?.value||'top';return rows.slice().sort((a,b)=>dir==='bottom'?(a[key]-b[key]):(b[key]-a[key]))}
function visibleRows(rows){return rows.slice(0,+($('topN')?.value||25))}
function safeCenterZip(){return String($('centerZip')?.value||'').replace(/\D/g,'').slice(0,5)}
function zipRecord(z){return ZIP.find(r=>r.zip===z)}
function centroidFor(rows){const ok=rows.filter(r=>Number.isFinite(+r.lat)&&Number.isFinite(+r.lon));if(!ok.length)return null;const w=ok.reduce((s,r)=>s+(+r.households||1),0);return {lat:ok.reduce((s,r)=>s+(+r.lat)*(+r.households||1),0)/w,lon:ok.reduce((s,r)=>s+(+r.lon)*(+r.households||1),0)/w}}
const DMA_CBSA={"532":"10580","790":"10740","524":"12060","635":"12420","800":"12540","512":"12580","630":"13820","506":"14460","514":"15380","564":"16620","517":"16740","575":"16860","602":"16980","515":"17140","510":"17410","752":"17820","535":"18140","623":"19100","542":"19430","751":"19740","679":"19780","505":"19820","765":"21340","513":"22420","571":"15980","866":"23420","563":"24340","658":"24580","518":"24660","567":"24860","636":"32580","566":"25420","533":"25540","744":"46520","618":"26420","527":"26900","561":"27260","616":"28140","557":"28940","839":"29820","541":"30460","693":"30780","803":"31080","529":"31140","640":"32820","528":"33100","617":"33340","613":"33460","686":"37860","659":"34980","622":"35380","501":"35620","544":"47260","650":"36420","652":"36540","534":"36740","804":"PALM","504":"37980","753":"38060","508":"38300","820":"38900","521":"39300","560":"39580","556":"40060","573":"40220","538":"40380","862":"40900","770":"41620","641":"41700","825":"41740","807":"41860","819":"42660","881":"44060","609":"41180","555":"45060","539":"45300","547":"45780","789":"46060","671":"46140","511":"47900","548":"38940","678":"48620","577":"42540"};
function dmaCentroid(r){
 const key=DMA_CBSA[String(r.dma_code)]||DMA_CBSA[r.dma_code];
 if(key==='PALM')return {lat:33.8303,lon:-116.5453};
 if(key){const c=centroidFor(ZIP.filter(z=>String(z.cbsa)===String(key)));if(c)return c}
 return null
}
let GEO_MAP=null,GEO_LAYER=null,GEO_RADIUS=null,GEO_RENDERER=null;
function ensureLeafletMap(){const el=$('map');if(!el||typeof L==='undefined')return null;if(!GEO_MAP){el.innerHTML='';GEO_MAP=L.map(el,{scrollWheelZoom:false,zoomControl:true,attributionControl:true});GEO_MAP.createPane('opportunityMarkers');GEO_MAP.getPane('opportunityMarkers').style.zIndex='650';GEO_MAP.getPane('opportunityMarkers').style.pointerEvents='auto';GEO_RENDERER=L.canvas({pane:'opportunityMarkers',padding:0.5});const primary=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'});let switched=false;primary.on('tileerror',()=>{if(switched)return;switched=true;try{GEO_MAP.removeLayer(primary)}catch(e){}L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{maxZoom:19,subdomains:'abcd',attribution:'&copy; OpenStreetMap contributors &copy; CARTO'}).addTo(GEO_MAP)});primary.addTo(GEO_MAP);GEO_MAP.setView([39.5,-98.35],4)}if(GEO_LAYER)GEO_LAYER.clearLayers();else GEO_LAYER=L.layerGroup().addTo(GEO_MAP);if(GEO_RADIUS){GEO_MAP.removeLayer(GEO_RADIUS);GEO_RADIUS=null}return GEO_MAP}
function renderGeoMap(rows,labelFn,scoreFn,selectedLabel,opts={}){const el=$('map');if(!el)return;const map=ensureLeafletMap();if(!map){el.innerHTML='<div class="map-empty">Map tiles could not be loaded. Rankings and calculations remain available.</div>';return}let mapRows=opts.allRows?rows.slice():visibleRows(rows);const selectedRow=rows.find(r=>labelFn(r)===selectedLabel);if(selectedRow&&!mapRows.includes(selectedRow))mapRows=mapRows.concat([selectedRow]);let pts=[];for(const r of mapRows){let c;if(r.lat!=null)c={lat:+r.lat,lon:+r.lon};else if(r.fips)c=centroidFor(ZIP.filter(z=>z.fips===r.fips));else if(r.cbsa)c=centroidFor(ZIP.filter(z=>z.cbsa===r.cbsa));else if(r.dma_code!=null)c=dmaCentroid(r);if(c&&Number.isFinite(c.lat)&&Number.isFinite(c.lon))pts.push({...c,label:labelFn(r),score:+scoreFn(r),selected:labelFn(r)===selectedLabel,row:r})}
 const bounds=[];for(const p of pts){let marker;if(opts.usView){const size=p.selected?18:12;const icon=L.divIcon({className:'dma-div-icon',html:`<span class="dma-dot${p.selected?' selected':''}" style="width:${size}px;height:${size}px"></span>`,iconSize:[size,size],iconAnchor:[size/2,size/2]});marker=L.marker([p.lat,p.lon],{icon,pane:'markerPane',keyboard:true,title:p.label,zIndexOffset:p.selected?1000:0})}else{const radius=4+Math.max(0,Math.min(100,p.score))/22;marker=L.circleMarker([p.lat,p.lon],{radius:p.selected?Math.max(9,radius+3):Math.max(6,radius),weight:p.selected?4:2,opacity:1,fillOpacity:p.selected?1:.72,color:p.selected?'#17242b':'#315c6a',fillColor:p.selected?'#8fcf46':'#4f9e68',renderer:GEO_RENDERER,pane:'opportunityMarkers'})}marker.bindPopup(`<div class="map-popup"><b>${p.label}</b><span>Market Opportunity: ${score(p.score)}</span></div>`);marker.addTo(GEO_LAYER);bounds.push([p.lat,p.lon])}
 if(opts.center&&Number.isFinite(+opts.center.lat)&&Number.isFinite(+opts.center.lon)){const c=[+opts.center.lat,+opts.center.lon];L.circleMarker(c,{radius:7,weight:3,fillOpacity:1,renderer:GEO_RENDERER,pane:'opportunityMarkers'}).bindTooltip('Center ZIP '+opts.center.zip).addTo(GEO_LAYER);bounds.push(c);if(opts.radiusMiles>0){GEO_RADIUS=L.circle(c,{radius:+opts.radiusMiles*1609.344,weight:2,fillOpacity:0.05}).addTo(map)}}
 if(opts.usView){const usBounds=L.latLngBounds([[24.4,-125.0],[49.5,-66.5]]),usCenter=usBounds.getCenter();const frameUS=()=>{map.invalidateSize();map.setMaxBounds(null);const z=map.getBoundsZoom(usBounds,true,[18,18]);map.setView(usCenter,Math.min(7,Math.max(5,z)),{animate:false});map.setMaxBounds(usBounds.pad(0.04))};frameUS();setTimeout(frameUS,120)}
 else if(opts.focusSelected){map.setMaxBounds(null);const sp=pts.find(p=>p.selected);if(sp){const target=[sp.lat,sp.lon],targetZoom=opts.focusZoom||7;const lockFocus=()=>{map.invalidateSize({pan:false});map.setView(target,targetZoom,{animate:false,reset:true})};lockFocus();setTimeout(lockFocus,80);setTimeout(lockFocus,300)}else if(bounds.length){map.setMaxBounds(null);map.fitBounds(bounds,{padding:[28,28],maxZoom:opts.maxZoom||7});setTimeout(()=>map.invalidateSize(),0)}else{map.setView([39.5,-98.35],4);setTimeout(()=>map.invalidateSize(),0)}}
 else if(bounds.length){map.fitBounds(bounds,{padding:[28,28],maxZoom:opts.radiusMiles?10:opts.maxZoom||7});setTimeout(()=>map.invalidateSize(),0)}else{map.setView([39.5,-98.35],4);setTimeout(()=>map.invalidateSize(),0)}
}
function rowsToTable(rows,html){return visibleRows(rows).map(html).join('')}

// Override setup to support independent service-area radius.
function setup(){const m=mode(),s=$('market');$('stageNotice').classList.add('hidden');$('view').style.display='block';$('marketWrap').style.display='block';$('countyWrap').style.display='none';$('radiusWrap').style.display='none';if($('centerZipWrap'))$('centerZipWrap').style.display='none';
 if(m==='Media Market'){s.innerHTML=DMA.slice().sort((a,b)=>a.dma.localeCompare(b.dma)).map(x=>`<option value="${x.dma_code}">${x.dma}</option>`).join('');if(DMA.some(x=>x.dma_code===751))s.value='751';}
 else{s.innerHTML=METRO.slice().sort((a,b)=>a.metro.localeCompare(b.metro)).map(x=>`<option value="${x.cbsa}">${x.metro}</option>`).join('');if(METRO.some(x=>x.cbsa==='19740'))s.value='19740';if(m==='Neighborhood Targeting'){$('countyWrap').style.display='block';$('radiusWrap').style.display='block';if($('centerZipWrap'))$('centerZipWrap').style.display='block';setupCounty();return;}}
 render()}
function setupCounty(){const cb=$('market').value,cs=COUNTY.filter(x=>x.cbsa===cb).sort((a,b)=>a.county.localeCompare(b.county));$('county').innerHTML=cs.map(x=>`<option value="${x.fips}">${x.county} County</option>`).join('');if(cb==='19740'&&cs.some(x=>x.fips==='08031'))$('county').value='08031';const base=ZIP.filter(r=>r.cbsa===cb&&r.fips===$('county').value).sort((a,b)=>b.households-a.households);if($('centerZip')&&!safeCenterZip()&&base[0])$('centerZip').value=base[0].zip;render()}
function marketChanged(){if(mode()==='Neighborhood Targeting')setupCounty();else render()}


function wavg(rows,field,weight='owner_hh'){let n=0,d=0;rows.forEach(r=>{const v=+r[field],w=Math.max(0,+r[weight]||+r.households||1);if(Number.isFinite(v)&&w>0){n+=v*w;d+=w}});return d?n/d:0}
function index100(value,rows,field,weight='owner_hh'){const b=wavg(rows,field,weight);return b?Math.round((+value/b)*100):100}
function intelCard(label,value,note=''){return `<div class="intel-card"><span>${label}</span><b>${value}</b>${note?`<small>${note}</small>`:''}</div>`}

function categoryName(cat){return cat==='hvac'?'HVAC':cat==='roofing'?'Roofing':'Window & Door'}
function upgradeLabel(cat){return 'Replacement Potential'}
function serviceNeedLabel(cat){return cat==='hvac'?'HVAC System Need':categoryName(cat)+' Need'}
function renderIntelligence(cat,m,x,rows){if(!$('intelGrid'))return;let cards=[],tips=[];const catName=cat==='hvac'?'HVAC':cat==='roofing'?'Roofing':'Windows & Doors';
 if(m==='Media Market'){const rep=index100(x.replacement_ready,DMA,'replacement_ready'),need=index100(x[cat+'_need'],DMA,cat+'_need');cards=[['Replacement Potential',rep,'Housing-stock replacement propensity'],[serviceNeedLabel(cat),need,catName+' need estimate'],['Homeowner Market Size',score(x.market_scale),'Relative homeowner market scale'],['Homeowner Households',fmt(x.owner_hh),'Homeowner market size'],['Residential ZIP Codes',fmt(x.zip_count),'Residential coverage']];const signals=[['replacement potential',rep],['need',need]].sort((a,b)=>b[1]-a[1]);tips.push(`${signals[0][0][0].toUpperCase()+signals[0][0].slice(1)} is the strongest relative signal at an index of ${signals[0][1]}.`);tips.push(`${fmt(x.owner_hh)} owner households provide the scale behind the market ranking.`)}
 else if(m==='Local Opportunity'){const nat=COUNTY,rep=index100(x.replacement_ready,nat,'replacement_ready'),need=index100(x[cat+'_need'],nat,cat+'_need');cards=[['Replacement Potential',rep,'U.S. Average = 100'],['Need',need,catName+' service-need estimate'],['Replacement Potential Households',fmt(x.replacement_ready_hh),'Modeled household count'],['Homeowner Households',fmt(x.owner_hh),'Homeowner market size'],['Residential ZIP Codes',fmt(x.zip_count),'County coverage']];tips.push(`${x.county} County ${rep>=100?'is above average':'is below average'} for upgrade potential versus the national county benchmark.`);tips.push(`${catName} service need is ${need}, helping explain its position within the selected Metro.`)}
 else if(m==='Neighborhood Targeting'){const nat=ZIP,rep=index100(x.replacement_ready,nat,'replacement_ready'),need=index100(x[cat+'_need'],nat,cat+'_need'),inc=index100(x.income,nat,'income','households'),old=index100(x.old_rate,nat,'old_rate'),sf=index100(x.sf_rate,nat,'sf_rate');const total=rows.reduce((a,r)=>a+(+r.replacement_ready_hh||0),0),top10=rows.slice().sort((a,b)=>b[cat+'_score']-a[cat+'_score']).slice(0,10).reduce((a,r)=>a+(+r.replacement_ready_hh||0),0),conc=total?Math.round(100*top10/total):0;cards=[['Replacement Potential',rep,'National ZIP benchmark = 100'],['Need',need,catName+' service-need estimate'],['Median HHI',x.income?'$'+Math.round(x.income).toLocaleString():'—',`Income index ${inc}`],['Older-Home Index',old,'Housing-age concentration'],['Single-Family Index',sf,`${score(x.sf_rate)}% single-family`],['Homeowner Households',fmt(x.owner_hh),`${score(x.owner_rate)}% owner occupied`]];if(rows.length>1)cards.push(['Opportunity Concentration',conc+'%',`Share of replacement-potential HH in top ${Math.min(10,rows.length)} ranked ZIPs`]);tips.push(`ZIP ${x.zip} ${rep>=100?'is above average':'is below average'} for upgrade potential and has a ${need} ${catName} Need.`);tips.push(`Median household income is ${x.income?'$'+Math.round(x.income).toLocaleString():'not available'}; single-family housing represents ${score(x.sf_rate)}% of households in the source layer.`);if(rows.length>1)tips.push(`The top ${Math.min(10,rows.length)} ranked ZIPs contain about ${conc}% of replacement-potential households in the current view.`)}
 else {cards=[['Expansion Opportunity',score(x[cat]),'Category-specific expansion model'],['Business Establishments',fmt(x[cat+'_estab']),'Selected-category establishments'],['Businesses with 10+ Employees',fmt(x[cat+'_10plus']),'Selected-category larger operators'],['Businesses with 50+ Employees',fmt(x[cat+'_50plus']),'Selected-category scaled operators'],['Contractor Market Strength',score(x.contractor_ecosystem),'Expansion-model component']];tips.push(`${x.metro} is evaluated as an operator-expansion market using establishment scale and contractor ecosystem—not DMA Scarborough data.`)}
 $('intelGrid').innerHTML=cards.map(c=>intelCard(...c)).join('');$('intelTakeaways').innerHTML=`<strong>What stands out</strong><ul>${tips.map(t=>`<li>${t}</li>`).join('')}</ul>`;$('intelNote').textContent=m==='Neighborhood Targeting'?'Local housing, household economics and concentration signals for the current ZIP/service-area view.':'Research signals that explain the selected market opportunity.'}

function explainIndexPosition(v){
  v=Number(v);
  if(!Number.isFinite(v)) return 'not available';
  if(v>=110) return 'well above the U.S. average';
  if(v>=102) return 'above the U.S. average';
  if(v>98) return 'about in line with the U.S. average';
  if(v>90) return 'below the U.S. average';
  return 'well below the U.S. average';
}
function tellUsNarrative(cat,replacement,need,marketSize){
  const c=categoryName(cat);
  $('metrics').innerHTML=
    `<div class="metric"><div><b>Replacement Potential</b><div class="sub"><b>What it means:</b> Measures how strongly the market's housing stock and ownership characteristics indicate homes are entering the replacement cycle.<br><b>This market:</b> ${explainIndexPosition(replacement)} for ${c.toLowerCase()} replacement potential.</div></div></div>`+
    `<div class="metric"><div><b>${c} Need</b><div class="sub"><b>What it means:</b> Measures housing characteristics associated with physical need for ${c.toLowerCase()} replacement or service.<br><b>This market:</b> ${explainIndexPosition(need)} for this measure.</div></div></div>`+
    `<div class="metric"><div><b>Homeowner Market Size</b><div class="sub"><b>What it means:</b> Measures the relative size of the addressable homeowner audience.<br><b>This market:</b> ${explainIndexPosition(marketSize)} on the analyzer's market-size benchmark.</div></div></div>`+
    `<div class="sub" style="margin-top:14px"><b>Index guide:</b> 100 = U.S. average for Replacement Potential and Need.</div>`;
}

function renderDMA(cat){const code=+$('market').value,key=cat+'_opportunity',sorted=rankRows(DMA,key),x=DMA.find(r=>r.dma_code===code)||sorted[0];updateConditions(cat,'Media Market',x,sorted);renderIntelligence(cat,'Media Market',x,sorted);cards([['Market Opportunity',score(x[key])],[upgradeLabel(cat),index100(x.replacement_ready,DMA,'replacement_ready')],[serviceNeedLabel(cat),index100(x[cat+'_need'],DMA,cat+'_need')],['Homeowner Market Size',score(x.market_scale)]]);$('chartTitle').textContent='U.S. Media Market Opportunity';$('chartNote').textContent='Market opportunity across 83 DMAs using replacement potential, category need and homeowner market size.';$('marketName').textContent=x.dma;$('whyTitle').textContent='What the Numbers Tell Us';tellUsNarrative(cat,index100(x.replacement_ready,DMA,'replacement_ready'),index100(x[cat+'_need'],DMA,cat+'_need'),score(x.market_scale));$('method').textContent='Market Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size';bars(visibleRows(sorted),r=>r.dma,r=>r[key]);renderGeoMap(sorted,r=>r.dma,r=>r[key],x.dma,{usView:true,allRows:true});$('mapNote').textContent='DMA opportunities are plotted at representative market centroids; selected market is emphasized. DMA boundary geometry is not included in this release.';$('tableTitle').textContent='Media Market Rankings — The Ad Shop';$('thead').innerHTML='<tr><th>Rank</th><th>DMA</th><th>Market Opportunity</th><th>Homeowner Households</th><th>ZIP Codes</th></tr>';$('rankings').innerHTML=rowsToTable(sorted,(r,i)=>`<tr data-code="${r.dma_code}"><td>${i+1}</td><td>${r.dma}</td><td><b>${score(r[key])}</b></td><td>${fmt(r.owner_hh)}</td><td>${r.zip_count}</td></tr>`);rowClicks()}
function renderMetro(cat){const code=$('market').value,key=cat,sorted=rankRows(METRO,key),x=METRO.find(r=>r.cbsa===code)||sorted[0];updateConditions(cat,'Market Expansion',x,sorted);renderIntelligence(cat,'Market Expansion',x,sorted);cards([['Market Expansion Score',score(x[key])],['Business Establishments',fmt(x[cat+'_estab'])],['Businesses with 10+ Employees',fmt(x[cat+'_10plus'])],['Businesses with 50+ Employees',fmt(x[cat+'_50plus'])],['Contractor Market Strength',score(x.contractor_ecosystem)]]);$('chartTitle').textContent='U.S. Metro Expansion Opportunity';$('chartNote').textContent='387 metropolitan statistical areas only — micropolitan areas are excluded. Business counts reflect the selected category.';$('marketName').textContent=x.metro;$('whyTitle').textContent='What the Numbers Tell Us';metrics([['Market Expansion Score',score(x[key])],['Business Establishments',fmt(x[cat+'_estab'])],['Businesses with 10+ Employees',fmt(x[cat+'_10plus'])],['Businesses with 50+ Employees',fmt(x[cat+'_50plus'])],['Contractor Market Strength',score(x.contractor_ecosystem)]]);$('method').textContent='Market Expansion uses the CBSA employer/contractor model. Business counts shown are specific to the selected category.';bars(visibleRows(sorted),r=>r.metro,r=>r[key]);renderGeoMap(sorted,r=>r.metro,r=>r[key],x.metro,{focusSelected:true,focusZoom:7});$('mapNote').textContent='Selected metro shown in local context. National metro rankings remain available above and below the map.';$('tableTitle').textContent='Metro Rankings — The Operator';$('thead').innerHTML='<tr><th>Rank</th><th>Metro</th><th>Market Expansion</th><th>Business Establishments</th><th>10+ Employees</th><th>50+ Employees</th></tr>';$('rankings').innerHTML=rowsToTable(sorted,(r,i)=>`<tr data-code="${r.cbsa}"><td>${i+1}</td><td>${r.metro}</td><td><b>${score(r[key])}</b></td><td>${fmt(r[cat+'_estab'])}</td><td>${fmt(r[cat+'_10plus'])}</td><td>${fmt(r[cat+'_50plus'])}</td></tr>`);rowClicks()}
function renderCounty(cat){const code=$('market').value,key=cat+'_score',sorted=rankRows(COUNTY.filter(r=>r.cbsa===code),key),x=sorted[0],metro=METRO.find(r=>r.cbsa===code);if(!x)return;updateConditions(cat,'Local Opportunity',x,sorted);renderIntelligence(cat,'Local Opportunity',x,sorted);cards([['Local Opportunity Score',score(x[key])],[upgradeLabel(cat),index100(x.replacement_ready,COUNTY,'replacement_ready')],[serviceNeedLabel(cat),index100(x[cat+'_need'],COUNTY,cat+'_need')],['Replacement Potential Households',fmt(x.replacement_ready_hh)],['Homeowner Households',fmt(x.owner_hh)]]);$('chartTitle').textContent=(metro?metro.metro:'Selected Metro')+' — County Opportunity';$('chartNote').textContent='Counties are ranked within the selected Metro using residential housing and homeowner data.';$('marketName').textContent=x.county+' County';$('whyTitle').textContent='What the Numbers Tell Us';tellUsNarrative(cat,index100(x.replacement_ready,COUNTY,'replacement_ready'),index100(x[cat+'_need'],COUNTY,cat+'_need'),score(x.market_scale));$('method').textContent='Local Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size.';bars(visibleRows(sorted),r=>r.county,r=>r[key]);renderGeoMap(sorted,r=>r.county+' County',r=>r[key],x.county+' County',{focusSelected:true,focusZoom:8});$('mapNote').textContent='County residential centroids on a geographic basemap within the selected Metro.';$('tableTitle').textContent='County Rankings — The Branch';$('thead').innerHTML='<tr><th>Rank</th><th>County</th><th>Local Opportunity</th><th>Replacement Potential Households</th><th>Homeowner Households</th><th>ZIP Codes</th></tr>';$('rankings').innerHTML=rowsToTable(sorted,(r,i)=>`<tr><td>${i+1}</td><td>${r.county}</td><td><b>${score(r[key])}</b></td><td>${fmt(r.replacement_ready_hh)}</td><td>${fmt(r.owner_hh)}</td><td>${r.zip_count}</td></tr>`)}
function renderZIP(cat){const cb=$('market').value,fips=$('county').value,rad=+$('radius').value,key=cat+'_score';let rows,center=null,centerZip=safeCenterZip();if(rad>0){center=zipRecord(centerZip);if(!center){const fallback=ZIP.filter(r=>r.cbsa===cb&&r.fips===fips).sort((a,b)=>b.households-a.households)[0];center=fallback;if(center&&$('centerZip'))$('centerZip').value=center.zip}rows=center?ZIP.filter(r=>miles(center.lat,center.lon,r.lat,r.lon)<=rad):[]}else rows=ZIP.filter(r=>r.cbsa===cb&&r.fips===fips);const sorted=rankRows(rows,key),x=sorted[0],metro=METRO.find(r=>r.cbsa===cb);if(!x){$('rankings').innerHTML='';return}updateConditions(cat,'Neighborhood Targeting',x,sorted);renderIntelligence(cat,'Neighborhood Targeting',x,sorted);cards([['Neighborhood Opportunity Score',score(x[key])],[upgradeLabel(cat),index100(x.replacement_ready,ZIP,'replacement_ready')],[serviceNeedLabel(cat),index100(x[cat+'_need'],ZIP,cat+'_need')],['Homeowner Households',fmt(x.owner_hh)],['ZIP Codes in View',sorted.length]]);$('chartTitle').textContent=rad?`Service Area · ZIP ${center.zip} · ${rad} miles`:(metro?metro.metro:'Selected Metro')+' — Neighborhood Targeting';$('chartNote').textContent=rad?`All residential ZIPs whose centroids fall within ${rad} straight-line miles of ZIP ${center.zip}; County, Metro and DMA boundaries do not constrain the service area.`:'Residential ZIP Codes in the selected county.';$('marketName').textContent='ZIP '+x.zip+' · '+x.county+' County';$('whyTitle').textContent='What the Numbers Tell Us';metrics([[upgradeLabel(cat),index100(x.replacement_ready,ZIP,'replacement_ready')],[serviceNeedLabel(cat),index100(x[cat+'_need'],ZIP,cat+'_need')],['Homeowner Market Size',score(x.addressable_scale)],['Homeowner Rate',score(x.owner_rate)+'%'],['Single-Family Home Rate',score(x.sf_rate)+'%']]);$('method').textContent='ZIP Opportunity = 40% Replacement Potential + 35% Need + 25% Homeowner Market Size. Radius uses great-circle distance between ZIP centroids and can cross County, Metro and DMA boundaries.';bars(visibleRows(sorted),r=>'ZIP '+r.zip,r=>r[key]);renderGeoMap(sorted,r=>'ZIP '+r.zip,r=>r[key],'ZIP '+x.zip,{center:rad?center:null,radiusMiles:rad,maxZoom:10});const counties=new Set(sorted.map(r=>r.fips).filter(Boolean)).size,metros=new Set(sorted.map(r=>r.cbsa).filter(Boolean)).size;$('mapNote').innerHTML=rad?`Residential ZIP centroids within ${rad} miles of ZIP ${center.zip}. <span class="radius-summary">${sorted.length} residential ZIPs · ${counties} counties · ${metros} metros</span>`:'Residential ZIP centroids in the selected county.';$('tableTitle').textContent='ZIP Rankings — The Local Pro';$('thead').innerHTML='<tr><th>Rank</th><th>ZIP</th><th>County</th><th>Metro</th><th>Neighborhood Opportunity</th><th>Replacement Potential Households</th><th>Homeowner Households</th><th>Homeowner %</th><th>Single-Family %</th></tr>';$('rankings').innerHTML=rowsToTable(sorted,(r,i)=>`<tr><td>${i+1}</td><td>${r.zip}</td><td>${r.county}</td><td>${r.metro||'—'}</td><td><b>${score(r[key])}</b></td><td>${fmt(r.replacement_ready_hh)}</td><td>${fmt(r.owner_hh)}</td><td>${score(r.owner_rate)}%</td><td>${score(r.sf_rate)}%</td></tr>`)}

// Replace the earlier ZIP methodology text with the locked independent service-area definition.
METHOD['Neighborhood Targeting'].data='Residential ZIP inputs include homeownership, single-family concentration, housing age, residence tenure, household economics and addressable household scale. Service Area Radius starts from the user-entered center ZIP and includes all residential ZIP centroids within the selected straight-line distance, regardless of County, Metro or DMA boundaries.';
METHOD['Neighborhood Targeting'].caution='No Scarborough propensity is represented as ZIP-level measurement. Radius uses ZIP centroid coordinates for targeting; Census ZCTA polygons, when used for display, are statistical approximations and not USPS delivery boundaries.';

window.addEventListener('DOMContentLoaded',()=>{if($('rankDir'))$('rankDir').onchange=render;if($('topN'))$('topN').onchange=render;if($('centerZip')){$('centerZip').oninput=e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,5);$('centerZip').onchange=()=>{if(+$('radius').value>0)render()}};$('county').onchange=()=>{if(mode()==='Neighborhood Targeting'){const base=ZIP.filter(r=>r.cbsa===$('market').value&&r.fips===$('county').value).sort((a,b)=>b.households-a.households);if(base[0]&&+$('radius').value===0)$('centerZip').value=base[0].zip}render()};$('radius').onchange=render});


function enforceBlankStartupMarket(){
  const a=$('analysis'), c=$('category'), m=$('market');
  if(!a||!c||!m) return;
  if(!a.value || !c.value){
    if(!m.querySelector('option[value=""]')){
      const o=document.createElement('option'); o.value=''; o.textContent='Select market...'; m.insertBefore(o,m.firstChild);
    }
    m.value='';
  }
}
enforceBlankStartupMarket();
